// ============================================================
// PARSE FORM
// ============================================================
const form = $input.first().json;

const brandName = (form['Brand Name'] || '').trim();
if (!brandName) throw new Error('Brand Name is required.');

const sheetUrl = form['Data Sheet URL (Google Sheets)'] || '';
const sheetIdMatch = sheetUrl.match(/\/d\/([a-zA-Z0-9_-]+)/);
const sheetId = sheetIdMatch ? sheetIdMatch[1] : '';
if (!sheetId) throw new Error('Invalid Google Sheet URL.');

const now = new Date();
const y1ago = new Date(now);
y1ago.setFullYear(y1ago.getFullYear() - 1);

return [{ json: {
  _brand_name: brandName,
  _brand_key: brandName.toLowerCase(),
  _vat_rate: parseFloat(form['VAT Rate']) || 0.23,
  _default_margin: parseFloat(form['Default Margin']) || 0.10,
  _feed_url: (form['Feed URL (XML)'] || '').trim(),
  _sheet_id: sheetId,
  _date_from: (form['Date From (YYYY-MM-DD)'] || '').trim() || y1ago.toISOString().split('T')[0],
  _date_to: (form['Date To (YYYY-MM-DD)'] || '').trim() || now.toISOString().split('T')[0],
  _form_ga4_id: (form['GA4 Property ID (opcjonalne)'] || '').trim(),
  _form_meta_id: (form['Meta Account ID (opcjonalne)'] || '').trim()
} }];

// ============================================================
// BUILD CONFIG + BRAND PERSISTENCE
// ============================================================

const formData = $node['Parse Form'].json;

const HARDCODED = {
  'iiyama':      { ga4: '280127077',  meta: 'act_1438113836305522' },
  'bushido':     { ga4: '297192186',  meta: 'act_1930400651212132' },
  'koszulkowy':  { ga4: '270928705',  meta: 'act_1897121353740892' },
  'mindlink':    { ga4: '477769901',  meta: 'act_1578563932814949' }
};

const sheetBrands = $input.all().map(i => i.json);
const sheetMatch = sheetBrands.find(row =>
  (row.brand_name || '').toLowerCase().trim() === formData._brand_key
);

const hardcoded = HARDCODED[formData._brand_key];
const ga4Id = formData._form_ga4_id
           || (sheetMatch ? (sheetMatch.ga4_property_id || '') : '')
           || (hardcoded ? hardcoded.ga4 : '');
const metaId = formData._form_meta_id
            || (sheetMatch ? (sheetMatch.meta_account_id || '') : '')
            || (hardcoded ? hardcoded.meta : '');

if (!ga4Id) throw new Error(`GA4 Property ID missing for "${formData._brand_name}"`);
if (!metaId) throw new Error(`Meta Account ID missing for "${formData._brand_name}"`);

const isNewBrand = !hardcoded && !sheetMatch;

return [{ json: {
  BRAND: formData._brand_name,
  VAT_RATE: formData._vat_rate,
  DEFAULT_MARGIN: formData._default_margin,
  FEED_URL: formData._feed_url,
  SHEET_ID: formData._sheet_id,
  GA4_PROPERTY_ID: ga4Id,
  META_ACCOUNT_ID: metaId,
  DATE_FROM: formData._date_from,
  DATE_TO: formData._date_to,
  MSC_ALGO: { MIN_META_TRANS: 10, MIN_ORGANIC_SESSIONS: 300 },
  _is_new_brand: isNewBrand
} }];

// ============================================================
// MARGIN RESOLVER — GATE NODE
// ============================================================

const rules = $input.all().map(item => ({
  match_type:  (item.json.match_type  || '').toUpperCase().trim(),
  match_value: (item.json.match_value || '').trim(),
  margin_rate: parseFloat(item.json.margin_rate) || 0
}));

const validTypes = ['SKU_EXACT', 'CATEGORY_EXACT', 'KEYWORD'];
const validRules = rules.filter(r => validTypes.includes(r.match_type) && r.margin_rate > 0);

const config = $node['Build Config'].json;

return [{ json: {
  ...config,
  MARGIN_RULES: validRules,
  MARGIN_RULES_COUNT: validRules.length,
  _resolver_executed: true
} }];

// NORMALIZE FEED + MARGINS
// FIX: g: namespace fields use bracket notation (p['g:id'] not p.g_id)
const config = $node['Margin Resolver'].json;
const marginRules = config.MARGIN_RULES || [];
const defaultMargin = config.DEFAULT_MARGIN || 0.10;

function normalizeUrl(url) {
  if (!url) return '';
  let u = url.toLowerCase().replace(/^https?:\/\/(www\.)?/, '').split('?')[0].replace(/\/$/, '');
  return u;
}

function resolveMargin(feedId, feedCategory) {
  const id = (feedId || '').trim();
  const cat = (feedCategory || '').toLowerCase().trim();
  for (const rule of marginRules) {
    if (rule.match_type === 'SKU_EXACT' && id === rule.match_value) return rule.margin_rate;
    if (rule.match_type === 'CATEGORY_EXACT' && cat === rule.match_value.toLowerCase()) return rule.margin_rate;
    if (rule.match_type === 'KEYWORD' && cat.includes(rule.match_value.toLowerCase())) return rule.margin_rate;
  }
  return defaultMargin;
}

const feedData = $input.first().json;
let products = [];
if (feedData.rss?.channel?.item) products = [feedData.rss.channel.item].flat();
else if (feedData.feed?.entry) products = [feedData.feed.entry].flat();
else if (feedData.products?.product) products = [feedData.products.product].flat();

return products.map(p => {
  // XML g: namespace produces keys like 'g:id', 'g:title', etc.
  const id = p['g:id'] || p.g_id || p.id || '';
  const cat = p['g:product_type'] || p['g:google_product_category'] || p.product_type || p.google_product_category || '';
  const link = p['g:link'] || p.g_link || p.link || '';
  const priceRaw = p['g:price'] || p.g_price || p.price || '0';
  const title = p['g:title'] || p.g_title || p.title || '';
  const brand = p['g:brand'] || p.g_brand || p.brand || '';

  return { json: {
    feed_id: id,
    feed_title: title,
    feed_brand: brand,
    feed_price: parseFloat(String(priceRaw).replace(/[^0-9.]/g, '')) || 0,
    feed_category: cat,
    feed_link: link,
    norm_url_path: normalizeUrl(link).split('/').slice(1).join('/'),
    base_gross_margin: resolveMargin(id, cat)
  }};
});

// NORMALIZE GA4 LP
return $input.first().json.rows.map(row => {
  const lp = row.dimensionValues[0].value || '';
  return { json: {
    ga4_lp_url: lp,
    ga4_norm_path: lp.toLowerCase().replace(/^\/|\/$/g, '').split('?')[0], // Match feed path
    ga4_sessions: parseInt(row.metricValues[0].value),
    ga4_revenue: parseFloat(row.metricValues[1].value),
    ga4_trans: parseInt(row.metricValues[2].value)
  }};
});

// NORMALIZE GA4 ITEMS
return $input.first().json.rows.map(row => {
  return { json: {
    ga4_item_id: row.dimensionValues[0].value,
    ga4_item_views: parseInt(row.metricValues[0].value),
    ga4_item_rev: parseFloat(row.metricValues[1].value),
    ga4_item_purch: parseInt(row.metricValues[2].value)
  }};
});

// NORMALIZE META ADS
const data = $input.first().json.data || [];
return data.map(ad => {
  const getVal = (list, type) => {
    if (!list) return 0;
    const m = list.find(x => x.action_type === type);
    return m ? parseFloat(m.value) : 0;
  };
  const purch = getVal(ad.actions, 'offsite_conversion.fb_pixel_purchase') || getVal(ad.actions, 'purchase');
  const val = getVal(ad.action_values, 'offsite_conversion.fb_pixel_purchase') || getVal(ad.action_values, 'purchase');
  const spend = parseFloat(ad.spend || '0');

  return { json: {
    meta_ad_id: ad.ad_id,
    meta_ad_name: ad.ad_name,
    meta_spend: spend,
    meta_purch: purch,
    meta_rev: val,
    meta_roas: spend > 0 ? val / spend : 0
  }};
});

// ============================================================
// PYTHON BRIDGE — Consolidate all data for external Python API
// ============================================================

const safeGet = (nodeName) => {
  try { return $(nodeName).all().map(i => i.json); }
  catch (e) { return []; }
};

const feed = safeGet('Normalize Feed + Margins');
const meta = safeGet('Normalize Meta Ads');
const items = safeGet('Normalize GA4 Items');
const lp = safeGet('Normalize GA4 LP');

let config = {};
try { config = $('Margin Resolver').first().json; } catch(e) {}

// Return consolidated payload as single item
return [{ json: {
  feed: feed,
  meta_ads: meta,
  ga4_items: items,
  ga4_lp: lp,
  config: {
    brand: config.BRAND || '',
    vat_rate: config.VAT_RATE || 0.23,
    default_margin: config.DEFAULT_MARGIN || 0.10,
    margin_rules: config.MARGIN_RULES || []
  }
} }];

// SAVE NEW BRAND CONFIG
const config = $node['Margin Resolver'].json;
if (!config._is_new_brand) return [];
return [{ json: {
  brand_name: config.BRAND,
  ga4_property_id: config.GA4_PROPERTY_ID,
  meta_account_id: config.META_ACCOUNT_ID,
  vat_rate: config.VAT_RATE,
  default_margin: config.DEFAULT_MARGIN,
  feed_url: config.FEED_URL,
  created_at: new Date().toISOString()
} }];

// ============================================================
// PARSE API RESPONSE
// Ensures Python API response is properly formatted for Sheets
// ============================================================
const items = $input.all().map(i => i.json);

// Handle case where response is nested in 'data' or similar
if (items.length === 1 && Array.isArray(items[0])) {
  return items[0].map(item => ({ json: item }));
}

// Already properly formatted
return items.map(item => ({ json: item }));
